const fs = require('fs');

function main() {
  const data = fs.readFileSync(0, 'utf8');
  let pos = 0;
  const len = data.length;

  function readInt() {
    while (pos < len) {
      const c = data.charCodeAt(pos);
      if (c >= 48 && c <= 57) break;
      pos++;
    }
    let x = 0;
    while (pos < len) {
      const c = data.charCodeAt(pos);
      if (c < 48 || c > 57) break;
      x = x * 10 + (c - 48);
      pos++;
    }
    return x;
  }

  const N = readInt(), M = readInt(), C = readInt();

  // Para cada música D, guardamos a música adorada (A) do amigo de menor índice
  // (cliente mais antigo) que detesta D. Como a transição depende apenas da
  // música atual, o próximo estado é determinístico.
  const nextSong = new Int32Array(M + 1); // 0 = ninguém detesta essa música
  for (let i = 0; i < N; i++) {
    const A = readInt();
    const D = readInt();
    if (nextSong[D] === 0) nextSong[D] = A;
  }

  // Simulação: como cada música determina unicamente a próxima,
  // revisitar uma música implica ciclo infinito (-1).
  const visited = new Uint8Array(M + 1);
  let s = C, count = 0, ans;
  while (true) {
    if (visited[s]) { ans = -1; break; }
    visited[s] = 1;
    const ns = nextSong[s];
    if (ns === 0) { ans = count; break; } // ninguém detesta a música atual
    s = ns;
    count++;
  }

  process.stdout.write(String(ans) + '\n');
}

main();
